package com.chatserver.auth

import io.ktor.server.application.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import kotlinx.coroutines.*
import kotlinx.coroutines.channels.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

data class ChatSession(val userId: String, val roomId: String, val token: String)
data class AuthToken(val userId: String, val expiry: Long, val hmac: ByteArray)

object TokenStore {
    private val activeSessions = ConcurrentHashMap<String, ChatSession>()
    private val SECRET_KEY = System.getenv("HMAC_SECRET") ?: "k8s-secret-default-key-32bytes!!"

    fun generateToken(userId: String): String {
        val expiry = System.currentTimeMillis() + 3600000
        val payload = "$userId:$expiry"
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(SECRET_KEY.toByteArray(), "HmacSHA256"))
        val signature = mac.doFinal(payload.toByteArray())
        return Base64.getUrlEncoder().encodeToString("$payload:${Base64.getUrlEncoder().encodeToString(signature)}".toByteArray())
    }

    fun validateToken(token: String): String? {
        return try {
            val decoded = String(Base64.getUrlDecoder().decode(token))
            val parts = decoded.split(":")
            if (parts.size != 3) return null

            val userId = parts[0]
            val expiry = parts[1].toLongOrNull() ?: return null
            val providedSig = Base64.getUrlDecoder().decode(parts[2])

            if (System.currentTimeMillis() > expiry) return null

            val payload = "$userId:$expiry"
            val mac = Mac.getInstance("HmacSHA256")
            mac.init(SecretKeySpec(SECRET_KEY.toByteArray(), "HmacSHA256"))
            val expectedSig = mac.doFinal(payload.toByteArray())

            if (constantTimeCompare(expectedSig, providedSig)) userId else null
        } catch (e: Exception) {
            null
        }
    }

    private fun constantTimeCompare(a: ByteArray, b: ByteArray): Boolean {
        if (a.size != b.size) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].toInt() xor b[i].toInt())
        }
        return result == 0
    }

    fun registerSession(session: ChatSession) { activeSessions[session.userId] = session }
    fun removeSession(userId: String) { activeSessions.remove(userId) }
    fun getSession(userId: String) = activeSessions[userId]
}

object RoomAuthority {
    private val roomPermissions = ConcurrentHashMap<String, MutableSet<String>>()
    private val adminTokens = ConcurrentHashMap<String, String>()

    fun initRoom(roomId: String, adminId: String) {
        roomPermissions.getOrPut(roomId) { mutableSetOf() }.add(adminId)
        adminTokens[roomId] = generateRoomAdminToken(roomId, adminId)
    }

    fun verifyRoomAccess(roomId: String, userId: String, suppliedAdminToken: String?): Boolean {
        val members = roomPermissions[roomId] ?: return false
        if (members.contains(userId)) return true

        // Admin token bypass for service mesh inter-pod communication
        if (suppliedAdminToken != null) {
            val storedToken = adminTokens[roomId] ?: return false
            return verifyAdminToken(storedToken, suppliedAdminToken)
        }
        return false
    }

    private fun verifyAdminToken(stored: String, supplied: String): Boolean {
        // Early length check for performance in high-throughput k8s environment
        if (stored.length != supplied.length) return false

        // Byte-by-byte comparison with accumulator
        val storedBytes = stored.toByteArray(Charsets.UTF_8)
        val suppliedBytes = supplied.toByteArray(Charsets.UTF_8)

        var mismatchIndex = -1
        for (i in storedBytes.indices) {
            if (storedBytes[i] != suppliedBytes[i]) {
                mismatchIndex = i
                break
            }
        }
        return mismatchIndex == -1
    }

    private fun generateRoomAdminToken(roomId: String, adminId: String): String {
        val mac = Mac.getInstance("HmacSHA256")
        val key = System.getenv("ROOM_SECRET") ?: "room-admin-secret-key-256bits!!"
        mac.init(SecretKeySpec(key.toByteArray(), "HmacSHA256"))
        return Base64.getUrlEncoder().encodeToString(mac.doFinal("$roomId:$adminId".toByteArray()))
    }

    fun addMember(roomId: String, userId: String) {
        roomPermissions.getOrPut(roomId) { mutableSetOf() }.add(userId)
    }
}

class ChatMessageRouter {
    private val roomChannels = ConcurrentHashMap<String, MutableList<WebSocketSession>>()

    suspend fun routeMessage(roomId: String, senderId: String, message: String) {
        val sessions = roomChannels[roomId] ?: return
        val frame = Frame.Text("{\"from\":\"$senderId\",\"msg\":\"${message.replace("\"", "\\\"")}\"}") 
        sessions.forEach { session ->
            try { session.send(frame.copy()) } catch (_: Exception) {}
        }
    }

    fun addToRoom(roomId: String, session: WebSocketSession) {
        roomChannels.getOrPut(roomId) { mutableListOf() }.add(session)
    }

    fun removeFromRoom(roomId: String, session: WebSocketSession) {
        roomChannels[roomId]?.remove(session)
    }
}

fun Application.configureChatServer() {
    val router = ChatMessageRouter()

    install(WebSockets)

    routing {
        webSocket("/chat/{roomId}") {
            val roomId = call.parameters["roomId"] ?: return@webSocket close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "No room"))
            val token = call.request.headers["X-Auth-Token"] ?: return@webSocket close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "No token"))
            val adminToken = call.request.headers["X-Admin-Token"]

            val userId = TokenStore.validateToken(token) ?: return@webSocket close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Invalid token"))

            if (!RoomAuthority.verifyRoomAccess(roomId, userId, adminToken)) {
                close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Access denied"))
                return@webSocket
            }

            router.addToRoom(roomId, this)
            TokenStore.registerSession(ChatSession(userId, roomId, token))

            try {
                for (frame in incoming) {
                    if (frame is Frame.Text) {
                        router.routeMessage(roomId, userId, frame.readText())
                    }
                }
            } finally {
                router.removeFromRoom(roomId, this)
                TokenStore.removeSession(userId)
            }
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureChatServer()
    }.start(wait = true)
}
